{
  "query": "SELECT Producer__c, Producer__r.Name, COUNT(Id) cnt, SUM(Annual_Premium__c) prem FROM Policy__c WHERE Status__c IN ('Active','Pending Renewal') AND Producer__c != null GROUP BY Producer__c, Producer__r.Name ORDER BY COUNT(Id) DESC LIMIT 5"
}

{
  "query": "SELECT Producer__r.Name, Line_of_Business__c, COUNT(Id) cnt, SUM(Annual_Premium__c) prem FROM Policy__c WHERE Status__c IN ('Active','Pending Renewal') AND Line_of_Business__c LIKE 'Worker%' GROUP BY Producer__r.Name, Line_of_Business__c ORDER BY COUNT(Id) DESC"
}
